-- P1: POS catalog, tables, single logical orders, kitchen tickets and cash tenders.
-- Filename generated by `supabase migration new p1_pos_foundation` in the isolated CI runner.
-- Draft is validated only on a local disposable Supabase database; never deploy to production without approval.

begin;

create table public.menu_items (
    id uuid primary key default gen_random_uuid(),
    organization_id uuid not null,
    branch_id uuid not null,
    name text not null check (length(btrim(name)) between 1 and 160),
    sku text,
    category_name text,
    price_minor bigint not null check (price_minor between 0 and 1000000000),
    currency_code text not null default 'PHP'
      check (currency_code ~ '^[A-Z]{3}$'),
    is_active boolean not null default true,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    unique (id, organization_id, branch_id),
    unique (organization_id, branch_id, sku),
    foreign key (branch_id, organization_id)
      references public.branches(id, organization_id) on delete cascade
);

create table public.restaurant_tables (
    id uuid primary key default gen_random_uuid(),
    organization_id uuid not null,
    branch_id uuid not null,
    name text not null check (length(btrim(name)) between 1 and 80),
    area_name text,
    capacity integer not null default 2 check (capacity between 1 and 100),
    status text not null default 'available'
      check (status in ('available', 'occupied', 'reserved', 'inactive')),
    is_active boolean not null default true,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    unique (id, organization_id, branch_id),
    unique (organization_id, branch_id, name),
    foreign key (branch_id, organization_id)
      references public.branches(id, organization_id) on delete cascade
);

create table public.orders (
    id uuid primary key,
    organization_id uuid not null,
    branch_id uuid not null,
    device_id uuid not null,
    local_order_number bigint not null check (local_order_number > 0),
    status text not null default 'saved'
      check (status in ('saved', 'preparing', 'ready', 'served', 'completed', 'cancelled')),
    order_type text not null
      check (order_type in ('dine_in', 'takeaway', 'delivery')),
    table_id uuid,
    subtotal_minor bigint not null check (subtotal_minor >= 0),
    tax_minor bigint not null default 0 check (tax_minor >= 0),
    discount_minor bigint not null default 0 check (discount_minor >= 0),
    total_minor bigint not null check (total_minor >= 0),
    currency_code text not null check (currency_code ~ '^[A-Z]{3}$'),
    note text,
    opened_by uuid references auth.users(id) on delete set null,
    idempotency_key uuid not null,
    request_fingerprint text not null check (request_fingerprint ~ '^[0-9a-f]{32}$'),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    unique (id, organization_id, branch_id),
    unique (organization_id, branch_id, idempotency_key),
    unique (organization_id, branch_id, device_id, local_order_number),
    foreign key (branch_id, organization_id)
      references public.branches(id, organization_id) on delete restrict,
    foreign key (table_id, organization_id, branch_id)
      references public.restaurant_tables(id, organization_id, branch_id) on delete restrict,
    check (subtotal_minor - discount_minor + tax_minor = total_minor),
    check ((order_type = 'dine_in' and table_id is not null)
        or (order_type <> 'dine_in' and table_id is null))
);

create unique index orders_one_active_order_per_table_idx
on public.orders (organization_id, branch_id, table_id)
where table_id is not null and status not in ('completed', 'cancelled');

create index orders_branch_status_created_idx
on public.orders (organization_id, branch_id, status, created_at desc);

create table public.order_lines (
    id uuid primary key default gen_random_uuid(),
    order_id uuid not null,
    organization_id uuid not null,
    branch_id uuid not null,
    catalog_item_id uuid not null,
    item_name_snapshot text not null check (length(btrim(item_name_snapshot)) > 0),
    sku_snapshot text,
    quantity_milli bigint not null check (quantity_milli between 1 and 1000000000),
    unit_price_minor bigint not null check (unit_price_minor between 0 and 1000000000),
    discount_minor bigint not null default 0 check (discount_minor >= 0),
    tax_minor bigint not null default 0 check (tax_minor >= 0),
    line_total_minor bigint not null check (line_total_minor >= 0),
    created_at timestamptz not null default now(),
    foreign key (order_id, organization_id, branch_id)
      references public.orders(id, organization_id, branch_id) on delete cascade,
    foreign key (catalog_item_id, organization_id, branch_id)
      references public.menu_items(id, organization_id, branch_id) on delete restrict,
    check (line_total_minor >= unit_price_minor * quantity_milli / 1000 - discount_minor)
);

create index order_lines_order_idx on public.order_lines(order_id);

create table public.kitchen_tickets (
    id uuid primary key,
    organization_id uuid not null,
    branch_id uuid not null,
    order_id uuid not null unique,
    status text not null default 'queued'
      check (status in ('queued', 'preparing', 'ready', 'served', 'cancelled')),
    fired_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    foreign key (order_id, organization_id, branch_id)
      references public.orders(id, organization_id, branch_id) on delete cascade
);

create index kitchen_tickets_branch_status_idx
on public.kitchen_tickets (organization_id, branch_id, status, fired_at);

create table public.payments (
    id uuid primary key,
    organization_id uuid not null,
    branch_id uuid not null,
    order_id uuid not null,
    method text not null check (method = 'cash'),
    status text not null default 'captured' check (status = 'captured'),
    amount_minor bigint not null check (amount_minor > 0),
    currency_code text not null check (currency_code ~ '^[A-Z]{3}$'),
    idempotency_key uuid not null,
    request_fingerprint text not null check (request_fingerprint ~ '^[0-9a-f]{32}$'),
    actor_id uuid references auth.users(id) on delete set null,
    created_at timestamptz not null default now(),
    unique (organization_id, branch_id, idempotency_key),
    foreign key (order_id, organization_id, branch_id)
      references public.orders(id, organization_id, branch_id) on delete restrict
);

create index payments_order_created_idx on public.payments(order_id, created_at);

alter table public.menu_items enable row level security;
alter table public.restaurant_tables enable row level security;
alter table public.orders enable row level security;
alter table public.order_lines enable row level security;
alter table public.kitchen_tickets enable row level security;
alter table public.payments enable row level security;

revoke all on table public.menu_items from anon, authenticated;
revoke all on table public.restaurant_tables from anon, authenticated;
revoke all on table public.orders from anon, authenticated;
revoke all on table public.order_lines from anon, authenticated;
revoke all on table public.kitchen_tickets from anon, authenticated;
revoke all on table public.payments from anon, authenticated;

grant select, insert, update, delete on public.menu_items to authenticated;
grant update (name, sku, category_name, price_minor, currency_code, is_active)
  on public.menu_items to authenticated;
grant select, insert, update, delete on public.restaurant_tables to authenticated;
grant update (name, area_name, capacity, status, is_active)
  on public.restaurant_tables to authenticated;
grant select on public.orders, public.order_lines, public.kitchen_tickets to authenticated;
grant select on public.payments to authenticated;

create policy menu_items_select_assigned_branch
on public.menu_items for select to authenticated
using ((select private.can_access_branch(branch_id)));

create policy menu_items_insert_owner_manager
on public.menu_items for insert to authenticated
with check ((select private.has_branch_role(branch_id, array['manager']::text[])));

create policy menu_items_update_owner_manager
on public.menu_items for update to authenticated
using ((select private.has_branch_role(branch_id, array['manager']::text[])))
with check ((select private.has_branch_role(branch_id, array['manager']::text[])));

create policy menu_items_delete_owner_manager
on public.menu_items for delete to authenticated
using ((select private.has_branch_role(branch_id, array['manager']::text[])));

create policy restaurant_tables_select_assigned_branch
on public.restaurant_tables for select to authenticated
using ((select private.can_access_branch(branch_id)));

create policy restaurant_tables_insert_owner_manager
on public.restaurant_tables for insert to authenticated
with check ((select private.has_branch_role(branch_id, array['manager']::text[])));

create policy restaurant_tables_update_owner_manager
on public.restaurant_tables for update to authenticated
using ((select private.has_branch_role(branch_id, array['manager']::text[])))
with check ((select private.has_branch_role(branch_id, array['manager']::text[])));

create policy restaurant_tables_delete_owner_manager
on public.restaurant_tables for delete to authenticated
using ((select private.has_branch_role(branch_id, array['manager']::text[])));

create policy orders_select_assigned_branch
on public.orders for select to authenticated
using ((select private.can_access_branch(branch_id)));

create policy order_lines_select_assigned_branch
on public.order_lines for select to authenticated
using ((select private.can_access_branch(branch_id)));

create policy kitchen_tickets_select_assigned_branch
on public.kitchen_tickets for select to authenticated
using ((select private.can_access_branch(branch_id)));

create policy payments_select_counter_or_manager
on public.payments for select to authenticated
using ((select private.has_branch_role(branch_id, array['counter', 'manager']::text[])));

create or replace function public.save_order(
    p_order_id uuid,
    p_organization_id uuid,
    p_branch_id uuid,
    p_device_id uuid,
    p_local_order_number bigint,
    p_idempotency_key uuid,
    p_kitchen_ticket_id uuid,
    p_order_type text,
    p_table_id uuid,
    p_note text,
    p_lines jsonb
)
returns table (
    order_id uuid,
    order_status text,
    local_order_number bigint,
    total_minor bigint,
    currency_code text,
    kitchen_ticket_id uuid,
    already_saved boolean
)
language plpgsql
security definer
set search_path = ''
as $$
declare
    v_actor uuid := (select auth.uid());
    v_fingerprint text;
    v_existing public.orders%rowtype;
    v_menu_item public.menu_items%rowtype;
    v_line jsonb;
    v_line_id uuid;
    v_item_id uuid;
    v_quantity_milli bigint;
    v_supplied_price bigint;
    v_line_total numeric;
    v_subtotal numeric := 0;
    v_order_total bigint;
    v_currency text := 'PHP';
    v_line_count integer;
    v_table_status text;
begin
    if v_actor is null then
        raise exception 'Authentication required' using errcode = '42501';
    end if;

    if not (select private.has_branch_role(p_branch_id, array['counter', 'manager']::text[]))
       or not exists (
            select 1 from public.branches b
            where b.id = p_branch_id and b.organization_id = p_organization_id and b.is_active
       ) then
        raise exception 'No access to the selected branch' using errcode = '42501';
    end if;

    if p_order_id is null or p_device_id is null or p_idempotency_key is null
       or p_kitchen_ticket_id is null or p_local_order_number is null
       or p_local_order_number < 1 then
        raise exception 'Invalid order identifiers' using errcode = '22023';
    end if;

    if p_order_type not in ('dine_in', 'takeaway', 'delivery') then
        raise exception 'Invalid order type' using errcode = '22023';
    end if;
    if p_order_type = 'dine_in' and p_table_id is null then
        raise exception 'Dine-in orders require a table' using errcode = '22023';
    end if;
    if p_order_type <> 'dine_in' and p_table_id is not null then
        raise exception 'Only dine-in orders can reserve a table' using errcode = '22023';
    end if;
    if p_order_type = 'dine_in' then
        select t.status into v_table_status
        from public.restaurant_tables t
        where t.id = p_table_id and t.organization_id = p_organization_id
          and t.branch_id = p_branch_id and t.is_active and t.status <> 'inactive'
        for update;
        if not found then
            raise exception 'Table is missing or belongs to another branch' using errcode = '22023';
        end if;
    end if;

    if jsonb_typeof(p_lines) <> 'array' then
        raise exception 'Order lines must be a JSON array' using errcode = '22023';
    end if;
    v_line_count := jsonb_array_length(p_lines);
    if v_line_count < 1 or v_line_count > 250 then
        raise exception 'An order must contain between 1 and 250 lines' using errcode = '22023';
    end if;

    v_fingerprint := md5(jsonb_build_object(
        'orderId', p_order_id,
        'organizationId', p_organization_id,
        'branchId', p_branch_id,
        'deviceId', p_device_id,
        'localOrderNumber', p_local_order_number,
        'kitchenTicketId', p_kitchen_ticket_id,
        'orderType', p_order_type,
        'tableId', p_table_id,
        'note', nullif(btrim(p_note), ''),
        'lines', p_lines
    )::text);

    select o.* into v_existing
    from public.orders o
    where o.organization_id = p_organization_id
      and o.branch_id = p_branch_id
      and o.idempotency_key = p_idempotency_key
    for update;

    if found then
        if v_existing.request_fingerprint <> v_fingerprint then
            raise exception 'Idempotency key reused with a different request' using errcode = '23505';
        end if;
        return query select v_existing.id, v_existing.status, v_existing.local_order_number,
            v_existing.total_minor, v_existing.currency_code,
            (select kt.id from public.kitchen_tickets kt where kt.order_id = v_existing.id), true;
        return;
    end if;

    if exists (select 1 from public.orders o where o.id = p_order_id) then
        raise exception 'Order ID already exists under a different request key' using errcode = '23505';
    end if;

    for v_line in select value from jsonb_array_elements(p_lines) as lines(value)
    loop
        begin
            v_line_id := coalesce(nullif(v_line->>'id', '')::uuid, gen_random_uuid());
            v_item_id := nullif(v_line->>'catalogItemId', '')::uuid;
            v_quantity_milli := (v_line->>'quantityMilli')::bigint;
            v_supplied_price := (v_line->>'unitPriceMinor')::bigint;
        exception when others then
            raise exception 'A line contains invalid identifiers or numeric fields' using errcode = '22023';
        end;

        if v_item_id is null or v_quantity_milli is null
           or v_quantity_milli < 1 or v_quantity_milli > 1000000000
           or v_supplied_price is null or v_supplied_price < 0 then
            raise exception 'Each line needs a menu item, positive quantity, and valid price'
              using errcode = '22023';
        end if;
        if coalesce((v_line->>'discountMinor')::bigint, 0) <> 0
           or coalesce((v_line->>'taxMinor')::bigint, 0) <> 0 then
            raise exception 'Discounts and taxes are not enabled in this first cloud order contract'
              using errcode = '0A000';
        end if;

        select mi.* into v_menu_item
        from public.menu_items mi
        where mi.id = v_item_id and mi.organization_id = p_organization_id
          and mi.branch_id = p_branch_id and mi.is_active
        for share;
        if not found then
            raise exception 'A menu item is inactive or belongs to another branch'
              using errcode = '22023';
        end if;
        if v_supplied_price <> v_menu_item.price_minor then
            raise exception 'Menu price changed; reload the menu and review this order'
              using errcode = '40001';
        end if;
        if v_menu_item.currency_code <> v_currency then
            if v_subtotal <> 0 then
                raise exception 'All menu items in an order must use one currency'
                  using errcode = '22023';
            end if;
            v_currency := v_menu_item.currency_code;
        end if;

        v_line_total := round(v_menu_item.price_minor::numeric * v_quantity_milli::numeric / 1000);
        if v_line_total < 0 or v_line_total > 9223372036854775807::numeric then
            raise exception 'Line total exceeds the supported monetary range' using errcode = '22003';
        end if;
        v_subtotal := v_subtotal + v_line_total;
        if v_subtotal > 9223372036854775807::numeric then
            raise exception 'Order total exceeds the supported monetary range' using errcode = '22003';
        end if;
    end loop;

    v_order_total := v_subtotal::bigint;

    insert into public.orders (
        id, organization_id, branch_id, device_id, local_order_number,
        status, order_type, table_id, subtotal_minor, tax_minor, discount_minor,
        total_minor, currency_code, note, opened_by, idempotency_key,
        request_fingerprint
    ) values (
        p_order_id, p_organization_id, p_branch_id, p_device_id, p_local_order_number,
        'saved', p_order_type, p_table_id, v_order_total, 0, 0, v_order_total,
        v_currency, nullif(btrim(p_note), ''), v_actor, p_idempotency_key, v_fingerprint
    );

    for v_line in select value from jsonb_array_elements(p_lines) as lines(value)
    loop
        v_line_id := coalesce(nullif(v_line->>'id', '')::uuid, gen_random_uuid());
        v_item_id := (v_line->>'catalogItemId')::uuid;
        v_quantity_milli := (v_line->>'quantityMilli')::bigint;
        v_supplied_price := (v_line->>'unitPriceMinor')::bigint;
        select mi.* into v_menu_item
        from public.menu_items mi
        where mi.id = v_item_id and mi.organization_id = p_organization_id
          and mi.branch_id = p_branch_id and mi.is_active;

        v_line_total := round(v_menu_item.price_minor::numeric * v_quantity_milli::numeric / 1000);
        insert into public.order_lines (
            id, order_id, organization_id, branch_id, catalog_item_id,
            item_name_snapshot, sku_snapshot, quantity_milli, unit_price_minor,
            discount_minor, tax_minor, line_total_minor
        ) values (
            v_line_id, p_order_id, p_organization_id, p_branch_id, v_item_id,
            v_menu_item.name, v_menu_item.sku, v_quantity_milli, v_menu_item.price_minor,
            0, 0, v_line_total::bigint
        );
    end loop;

    insert into public.kitchen_tickets (
        id, organization_id, branch_id, order_id, status
    ) values (
        p_kitchen_ticket_id, p_organization_id, p_branch_id, p_order_id, 'queued'
    );

    if p_table_id is not null then
        update public.restaurant_tables
          set status = 'occupied', updated_at = now()
        where id = p_table_id and organization_id = p_organization_id and branch_id = p_branch_id;
    end if;

    insert into public.audit_events (
        organization_id, branch_id, actor_id, action, entity_type, entity_id, metadata
    ) values (
        p_organization_id, p_branch_id, v_actor, 'order.created', 'order', p_order_id::text,
        jsonb_build_object('localOrderNumber', p_local_order_number, 'totalMinor', v_order_total)
    );

    return query select p_order_id, 'saved'::text, p_local_order_number,
        v_order_total, v_currency, p_kitchen_ticket_id, false;
end;
$$;

create or replace function public.transition_kitchen_ticket(
    p_ticket_id uuid,
    p_next_status text
)
returns table (
    ticket_id uuid,
    order_id uuid,
    ticket_status text,
    order_status text,
    updated_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
declare
    v_ticket public.kitchen_tickets%rowtype;
    v_actor uuid := (select auth.uid());
    v_order_status text;
    v_now timestamptz := now();
begin
    if v_actor is null then
        raise exception 'Authentication required' using errcode = '42501';
    end if;

    select kt.* into v_ticket
    from public.kitchen_tickets kt
    where kt.id = p_ticket_id
    for update;
    if not found then
        raise exception 'Kitchen ticket not found' using errcode = 'P0002';
    end if;
    if not (select private.has_branch_role(v_ticket.branch_id, array['kitchen', 'manager']::text[])) then
        raise exception 'No permission to transition this kitchen ticket' using errcode = '42501';
    end if;

    if p_next_status = v_ticket.status then
        return query select v_ticket.id, v_ticket.order_id, v_ticket.status,
            (select o.status from public.orders o where o.id = v_ticket.order_id), v_ticket.updated_at;
        return;
    end if;

    if not (
        (v_ticket.status = 'queued' and p_next_status in ('preparing', 'cancelled'))
        or (v_ticket.status = 'preparing' and p_next_status in ('ready', 'cancelled'))
        or (v_ticket.status = 'ready' and p_next_status in ('preparing', 'served'))
    ) then
        raise exception 'Invalid kitchen state transition' using errcode = '22023';
    end if;

    v_order_status := case p_next_status
        when 'queued' then 'saved'
        when 'preparing' then 'preparing'
        when 'ready' then 'ready'
        when 'served' then 'served'
        when 'cancelled' then 'cancelled'
        else null
    end;

    update public.kitchen_tickets
      set status = p_next_status, updated_at = v_now
    where id = p_ticket_id;

    update public.orders
      set status = v_order_status, updated_at = v_now
    where id = v_ticket.order_id
      and organization_id = v_ticket.organization_id
      and branch_id = v_ticket.branch_id;

    insert into public.audit_events (
        organization_id, branch_id, actor_id, action, entity_type, entity_id, metadata
    ) values (
        v_ticket.organization_id, v_ticket.branch_id, v_actor, 'kitchen.status_changed',
        'kitchen_ticket', p_ticket_id::text,
        jsonb_build_object('from', v_ticket.status, 'to', p_next_status, 'orderId', v_ticket.order_id)
    );

    return query select v_ticket.id, v_ticket.order_id, p_next_status,
        v_order_status, v_now;
end;
$$;

create or replace function public.record_cash_payment(
    p_payment_id uuid,
    p_organization_id uuid,
    p_branch_id uuid,
    p_order_id uuid,
    p_idempotency_key uuid,
    p_amount_minor bigint
)
returns table (
    payment_id uuid,
    order_id uuid,
    paid_minor bigint,
    due_minor bigint,
    order_status text,
    already_recorded boolean
)
language plpgsql
security definer
set search_path = ''
as $$
declare
    v_actor uuid := (select auth.uid());
    v_order public.orders%rowtype;
    v_existing public.payments%rowtype;
    v_fingerprint text;
    v_paid bigint;
    v_due bigint;
    v_status text;
begin
    if v_actor is null then
        raise exception 'Authentication required' using errcode = '42501';
    end if;
    if not (select private.has_branch_role(p_branch_id, array['counter', 'manager']::text[]))
       or not exists (
            select 1 from public.branches b
            where b.id = p_branch_id and b.organization_id = p_organization_id and b.is_active
       ) then
        raise exception 'No access to the selected branch' using errcode = '42501';
    end if;
    if p_payment_id is null or p_idempotency_key is null or p_amount_minor is null
       or p_amount_minor <= 0 then
        raise exception 'Invalid cash payment fields' using errcode = '22023';
    end if;

    select o.* into v_order
    from public.orders o
    where o.id = p_order_id and o.organization_id = p_organization_id
      and o.branch_id = p_branch_id
    for update;
    if not found then
        raise exception 'Order not found in the selected branch' using errcode = 'P0002';
    end if;

    v_fingerprint := md5(jsonb_build_object(
        'paymentId', p_payment_id, 'orderId', p_order_id,
        'organizationId', p_organization_id, 'branchId', p_branch_id,
        'amountMinor', p_amount_minor, 'currencyCode', v_order.currency_code
    )::text);

    select p.* into v_existing
    from public.payments p
    where p.organization_id = p_organization_id and p.branch_id = p_branch_id
      and p.idempotency_key = p_idempotency_key
    for update;
    if found then
        if v_existing.request_fingerprint <> v_fingerprint then
            raise exception 'Payment idempotency key reused with a different request' using errcode = '23505';
        end if;
        select coalesce(sum(p.amount_minor), 0)::bigint into v_paid
        from public.payments p
        where p.order_id = p_order_id and p.status = 'captured';
        return query select v_existing.id, p_order_id, v_paid,
            greatest(v_order.total_minor - v_paid, 0), v_order.status, true;
        return;
    end if;

    if v_order.status in ('completed', 'cancelled') then
        raise exception 'Order is already closed' using errcode = '22023';
    end if;

    select coalesce(sum(p.amount_minor), 0)::bigint into v_paid
    from public.payments p
    where p.order_id = p_order_id and p.status = 'captured';
    v_due := v_order.total_minor - v_paid;
    if p_amount_minor > v_due then
        raise exception 'Cash tender cannot exceed the remaining amount due' using errcode = '22023';
    end if;
    if p_amount_minor <= 0 then
        raise exception 'Cash payment must be positive' using errcode = '22023';
    end if;

    insert into public.payments (
        id, organization_id, branch_id, order_id, method, status, amount_minor,
        currency_code, idempotency_key, request_fingerprint, actor_id
    ) values (
        p_payment_id, p_organization_id, p_branch_id, p_order_id, 'cash', 'captured',
        p_amount_minor, v_order.currency_code, p_idempotency_key, v_fingerprint, v_actor
    );

    v_paid := v_paid + p_amount_minor;
    v_due := v_order.total_minor - v_paid;
    v_status := v_order.status;
    if v_due = 0 then
        v_status := 'completed';
        update public.orders set status = 'completed', updated_at = now()
        where id = p_order_id and organization_id = p_organization_id and branch_id = p_branch_id;
        if v_order.table_id is not null then
            update public.restaurant_tables
              set status = 'available', updated_at = now()
            where id = v_order.table_id and organization_id = p_organization_id
              and branch_id = p_branch_id and status = 'occupied';
        end if;
    end if;

    insert into public.audit_events (
        organization_id, branch_id, actor_id, action, entity_type, entity_id, metadata
    ) values (
        p_organization_id, p_branch_id, v_actor, 'payment.cash_recorded', 'payment', p_payment_id::text,
        jsonb_build_object('orderId', p_order_id, 'amountMinor', p_amount_minor, 'remainingMinor', v_due)
    );

    return query select p_payment_id, p_order_id, v_paid, v_due, v_status, false;
end;
$$;

revoke all on function public.save_order(uuid, uuid, uuid, uuid, bigint, uuid, uuid, text, uuid, text, jsonb) from public, anon;
revoke all on function public.transition_kitchen_ticket(uuid, text) from public, anon;
revoke all on function public.record_cash_payment(uuid, uuid, uuid, uuid, uuid, bigint) from public, anon;
grant execute on function public.save_order(uuid, uuid, uuid, uuid, bigint, uuid, uuid, text, uuid, text, jsonb) to authenticated;
grant execute on function public.transition_kitchen_ticket(uuid, text) to authenticated;
grant execute on function public.record_cash_payment(uuid, uuid, uuid, uuid, uuid, bigint) to authenticated;

commit;
